PROC gl_lookup_proc(const char *name)
{
    int i, n = (int)(sizeof(g_procs) / sizeof(g_procs[0]));
    char base[128];
    size_t len;
    if (!name) return NULL;
    for (i = 0; i < n; i++)
        if (strcmp(g_procs[i].n, name) == 0) return g_procs[i].p;
    len = strlen(name);
    if (len > 3 && len < sizeof(base)) {
        const char *suf = name + len - 3;
        if (strcmp(suf, "ARB") == 0 || strcmp(suf, "EXT") == 0 ||
            strcmp(suf, "NV") == 0) {
            memcpy(base, name, len - 3);
            base[len - 3] = 0;
            for (i = 0; i < n; i++)
                if (strcmp(g_procs[i].n, base) == 0) return g_procs[i].p;
        }
    }
    return NULL;
}

